SELECT AVG(duration) FROM (
    SELECT trip_id,
           (max(departure_seconds) - min(arrival_seconds)) / 60.0 AS duration
    FROM fact_stop_events
    GROUP BY trip_id
) AS t;

SELECT (COUNT(CASE WHEN dt.peak_period = 'peak' THEN 1 END) * 100.0 / COUNT(*)) AS percentage
FROM fact_stop_events f
JOIN dim_time dt ON f.time_key = dt.time_key;
